from __future__ import annotations

from datetime import datetime

from pydantic import BaseModel, Field

from meridian.schemas.analysis import PeerComparison, ValuationResult
from meridian.schemas.citations import Citation
from meridian.schemas.enums import FindingKind, LlmMode, ReportSection
from meridian.schemas.research import CompanyIdentity

DISCLAIMER = (
    "This report was generated by an automated multi-agent research system for informational and "
    "educational purposes only. It is not investment advice, a recommendation, or an offer to buy or sell "
    "any security. Figures may be incomplete, delayed or incorrect; agent-generated interpretation is "
    "clearly labelled and may be wrong. Verify all information against primary sources and consult a "
    "licensed financial professional before making investment decisions."
)


class ReportParagraph(BaseModel):
    """Text with inline citation markers of the form [ev_xxx] and an explicit content kind."""

    text: str
    kind: FindingKind
    evidence_ids: list[str] = Field(default_factory=list)
    metric_refs: list[str] = Field(default_factory=list)
    finding_ids: list[str] = Field(default_factory=list)
    unverified: bool = False


class ReportSectionContent(BaseModel):
    section: ReportSection
    title: str
    paragraphs: list[ReportParagraph] = Field(default_factory=list)


class ChartSeriesPoint(BaseModel):
    period: str
    value: float | None


class ChartSeries(BaseModel):
    key: str
    label: str
    unit: str
    points: list[ChartSeriesPoint]


class MetricRow(BaseModel):
    key: str
    label: str
    unit: str
    values: dict[str, float | None]  # period -> value
    formula: str


class ResearchReport(BaseModel):
    id: str
    session_id: str
    version: int = 1
    company: CompanyIdentity
    title: str
    generated_at: datetime
    llm_mode: LlmMode
    data_mode: str
    uses_snapshot_data: bool = False
    sections: list[ReportSectionContent]
    key_metrics: list[MetricRow] = Field(default_factory=list)
    charts: list[ChartSeries] = Field(default_factory=list)
    valuation: ValuationResult | None = None
    peers: PeerComparison | None = None
    citations: dict[str, Citation] = Field(default_factory=dict)  # evidence_id -> Citation
    unverified_claims: int = 0
    critic_rounds: int = 0
    disclaimer: str = DISCLAIMER
